// MySpace\MyS_Front\src\paginas\logeo\Cuenta.jsx

// YA ES FUNCIONAL - MODIFICADO PARA USAR DATOS DE EJEMPLO

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Cuenta.css";
import { login } from "../../Api";

// importe de la base
import Base_Main from "../../bases/Base_Main";

// **IMPORTACIÓN DE DATOS DE PERFIL**
import perfilData from "../../data/perfilData";

// Extraer el primer perfil para inicializar
const initialUserData = perfilData[0] || {};
const initialCorreo = initialUserData.correo || "";
const initialPass = initialUserData.password || "";

export default function CuentaPage() {

    const navigate = useNavigate();

    // Datos del usuario inicializados con los datos de ejemplo
    const [correo, setCorreo] = useState(initialCorreo);
    const [pass, setPass] = useState(initialPass);
    const [loading, setLoading] = useState(false);

    const logearUsuario = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            // Se usa la función `login` (asumiendo que está configurada correctamente en `../../Api`)
            const data = await login(correo, pass);
            console.log("Login exitoso:", data);
            alert(`¡Bienvenido ${data.usuario.nombre}!`);
            navigate("/perfil");
        } catch (error) {
            console.error("Error en login:", error);
            alert("Correo o contraseña incorrectos");
        } finally {
            setLoading(false);
        }
    };

    const passOlvidada = (e) => {
        e.preventDefault();
        if (!correo) {
            alert("Ingresa tu correo para recuperar la contraseña");
        } else {
            alert(`Se ha enviado un correo de recuperación a ${correo}`);
        }
    };

    return (
        <Base_Main tituloPagina="Iniciar Sesión">
            <div className="cuenta-content">
                <form className="cuenta-form" onSubmit={logearUsuario}>
                    <table>
                        <tbody>
                            <tr>
                                <td>Correo</td>
                                <td>
                                    <input
                                        type="email"
                                        name="correo"
                                        value={correo}
                                        onChange={(e) => setCorreo(e.target.value)}
                                        disabled={loading}
                                        required
                                    />
                                </td>
                            </tr>
                            <tr>
                                <td>Contraseña</td>
                                <td>
                                    <input
                                        type="password"
                                        name="pass"
                                        value={pass}
                                        onChange={(e) => setPass(e.target.value)}
                                        disabled={loading}
                                        required
                                    />
                                </td>
                            </tr>
                        </tbody>
                    </table>

                    <p><a href="#" onClick={passOlvidada}>¿Olvidaste tu contraseña?</a></p>
                    <button type="submit" className="cuenta-btn" disabled={loading}>
                        {loading ? "Iniciando sesión..." : "Iniciar Sesión"}
                    </button>

                    <p className="cuenta-login-text">¿Aún no tienes cuenta?</p>
                    <Link to="/registro">Registrarse</Link>
                </form>
            </div>
        </Base_Main>
    );
}
